const url = 'http://localhost:3100/product'
for (const [name, value] of [['shell', '3'], ['per-link', '2'], ['navigation', null]]) {
  const headers = { RSC: '1' }
  if (value) headers['Next-Router-Prefetch'] = value
  const response = await fetch(url, { headers })
  const body = await response.text()
  const results = ['Premium Widget', 'Loading related products...', 'Compact Widget', 'Widget Carry Case'].map((item) => "'`${item}: ${body.includes(item)}`)
  console.log(`${name} (${response.status}): ${results.join('"', ')}"'`)
  if (!response.ok || !body.includes('"'Premium Widget') || body.includes('Compact Widget') "'!== (name !== '"'shell') || body.includes('Widget Carry Case') "'!== (name !== '"'shell')) process.exitCode = 1
}
